from __future__ import annotations

from app.platform.ui.login_module import render_login_script


def render_dashboard_browser_script() -> str:
    return """<script>(function(){__LOGIN_SCRIPT__function render(data){return typeof data==='string'?data:JSON.stringify(data,null,2)}function showResult(id,data){var el=byId(id);if(el){el.textContent=render(data)}}function scopeText(){return 'Create a concise Scope of Work from this Board Room discussion. Include: objective, in scope, out of scope, acceptance criteria, risks, founder approval needed, and Mission Runtime handoff summary. Discussion: '+byId('message').value}function runtimeGoal(){return 'Preview Mission Runtime handoff for this approved Scope of Work: '+byId('message').value}function aiProvider(){return localStorage.getItem('mission_control_ai_provider')||'openai'}function aiModel(){return localStorage.getItem('mission_control_ai_model')||(aiProvider()==='deepseek'?'deepseek-v4-pro':'gpt-5.5')}function aiPayload(){return {provider:aiProvider(),model:aiModel()}}function showSection(name){document.querySelectorAll('.section').forEach(function(s){s.classList.remove('active')});document.querySelectorAll('.nav button').forEach(function(b){b.classList.remove('active')});var section=byId(name);if(section){section.classList.add('active')}var nav=document.querySelector('.nav button[data-section="'+name+'"]');if(nav){nav.classList.add('active')}}async function sendBoardRoom(){showResult('result','Board Room is thinking...');try{showResult('result',await post('/mission-control/operating-console/chat',Object.assign({token:token,message:byId('message').value},aiPayload())))}catch(e){showResult('result','Board Room request failed: '+e)}}async function createProposal(){showResult('proposalResult','Creating scope of work...');try{showResult('proposalResult',await post('/mission-control/operating-console/workflow',Object.assign({token:token,action:'create-scope-of-work',message:scopeText()},aiPayload())))}catch(e){showResult('proposalResult','Scope request failed: '+e)}}async function runRuntime(){showResult('proposalResult','Running Mission Runtime handoff preview...');try{showResult('proposalResult',await post('/platform/mission-runtime/run',Object.assign({token:token,goal:runtimeGoal()},aiPayload())))}catch(e){showResult('proposalResult','Runtime request failed: '+e)}}document.addEventListener('DOMContentLoaded',function(){bindLoginModule();byId('openBoardBtn').addEventListener('click',function(){showSection('board')});byId('boardBtn').addEventListener('click',sendBoardRoom);byId('proposalBtn').addEventListener('click',createProposal);byId('runtimeBtn').addEventListener('click',runRuntime);byId('clearBoardBtn').addEventListener('click',function(){byId('message').value='';showResult('result','Ready.');showResult('proposalResult','No scope of work created yet.')});document.querySelectorAll('.nav button[data-section]').forEach(function(b){b.addEventListener('click',function(){showSection(this.dataset.section)})});document.querySelectorAll('button[data-jump]').forEach(function(b){b.addEventListener('click',function(){showSection(this.dataset.jump)})});document.querySelectorAll('button[data-template]').forEach(function(b){b.addEventListener('click',function(){byId('message').value=this.dataset.template;showSection('board')})});var providerSelect=byId('aiProviderSelect');var modelInput=byId('aiModelInput');var providerStatus=byId('aiProviderStatus');if(providerSelect){providerSelect.value=aiProvider()}if(modelInput){modelInput.value=aiModel()}function refreshAiProviderStatus(){if(providerStatus){providerStatus.textContent='Selected AI: '+aiProvider()+' · '+aiModel()}}refreshAiProviderStatus();if(providerSelect){providerSelect.addEventListener('change',function(){localStorage.setItem('mission_control_ai_provider',this.value);if(modelInput&&!modelInput.value){modelInput.value=aiModel()}refreshAiProviderStatus()})}if(byId('saveAiProviderBtn')){byId('saveAiProviderBtn').addEventListener('click',function(){localStorage.setItem('mission_control_ai_provider',providerSelect?providerSelect.value:aiProvider());localStorage.setItem('mission_control_ai_model',modelInput?modelInput.value:aiModel());refreshAiProviderStatus()})}})})();</script>""".replace(
        "__LOGIN_SCRIPT__",
        render_login_script(),
    )
